     1→import type { MediaSourceInterface } from "@unomed/react-native-matrix-sdk";
     2→import { MatrixService } from "../services";
     3→import { getHttpUriForMxc } from "./getHttpUriForMxc";
     4→
     5→interface PropsWithUrl {
     6→  url: string;
     7→  serverUrl: string;
     8→  width?: number;
     9→  height?: number;
    10→  resizeMode?: "scale" | "crop";
    11→}
    12→
    13→interface PropsWithMediaSource {
    14→  serverUrl: string;
    15→  mediaSource: MediaSourceInterface;
    16→  mimeType?: string;
    17→}
    18→
    19→type Props = PropsWithUrl | PropsWithMediaSource;
    20→
    21→/**
    22→ * Fetches image from Matrix
    23→ * For MediaSource: Handles both encrypted and unencrypted images automatically
    24→ * For plain URL: Fetches from MXC URL (for avatars, etc.)
    25→ */
    26→export const fetchMedia = async (props: Props) => {
    27→  if (!MatrixService.instance) {
    28→    throw new Error("Matrix client not initialized");
    29→  }
    30→
    31→  try {
    32→    // Handle MediaSource (for message images - supports encryption)
    33→    if ("mediaSource" in props) {
    34→      const { mediaSource, mimeType = "image/jpeg" } = props;
    35→
    36→      // Use SDK's getMediaFile which handles decryption automatically
    37→      // Note: useCache is set to false to prevent stale temporary file paths
    38→      // iOS clears /tmp directory periodically, which would invalidate cached paths
    39→      const mediaHandle = await MatrixService.instance.getMediaFile(
    40→        mediaSource,
    41→        undefined, // filename
    42→        mimeType,
    43→        false, // useCache - disabled to prevent stale temp file issues
    44→        undefined, // tempDir - uses system default
    45→      );
    46→
    47→      const filePath = mediaHandle.path();
    48→      return filePath.startsWith("file://") ? filePath : `file://${filePath}`;
    49→    }
    50→
    51→    // Handle plain URL (for avatars, room images - typically unencrypted)
    52→    const {
    53→      url,
    54→      width = 32,
    55→      height = 32,
    56→      resizeMode = "scale",
    57→      serverUrl,
    58→    } = props;
    59→
    60→    const uri = getHttpUriForMxc(
    61→      serverUrl,
    62→      url,
    63→      width,
    64→      height,
    65→      resizeMode,
    66→      true,
    67→      true,
    68→      true,
    69→    );
    70→
    71→    if (!uri) return null;
    72→
    73→    const res = await fetch(uri, {
    74→      headers: {
    75→        Authorization: `Bearer ${MatrixService.instance.session().accessToken}`,
    76→      },
    77→    });
    78→
    79→    return res.url;
    80→  } catch (error) {
    81→    console.error("Failed to fetch image:", error);
    82→    return null;
    83→  }
    84→};
    85→

