    73→  if (isHidden) return null;
    74→
    75→  return (
    76→    <Block background={Colors.black} gap={8} align="center">
    77→      <Text>Debug Helpers</Text>
    78→      <Button title="Hide helpers" onPress={() => setisHidden(true)} />
    79→      <Button
    80→        title="Check Verification Status"
    81→        onPress={checkVerificationStatus}
    82→      />
    83→      <Button title="Logout" onPress={logout} />
    84→    </Block>
    85→  );
    86→};
