     1→import {
     2→  type FirebaseMessagingTypes,
     3→  getInitialNotification,
     4→  getMessaging,
     5→  getToken,
     6→  onMessage,
     7→  onNotificationOpenedApp,
     8→} from "@react-native-firebase/messaging";
     9→import { CallKitService } from "modules/call/service/CallKitService";
    10→import { MatrixStorage } from "modules/matrix-client/const/matrix-storage";
    11→import { MatrixService } from "modules/matrix-client/services/matrix-service";
    12→import { NavigationContainerRef } from "modules/navigation/const";
    13→import { Platform } from "react-native";
    14→import {
    15→  checkNotifications,
    16→  requestNotifications,
    17→  RESULTS,
    18→} from "react-native-permissions";
    19→import {
    20→  formatLocalPushNotificationMessage,
    21→  getDecryptedEventContent,
    22→  isDecryptedEventCall,
    23→} from "../util/formatLocalMessage";
    24→import { NotifeeService } from "./NotifeeService";
    25→
    26→/** Get the current user ID, works in both foreground and background */
    27→const getCurrentUserId = (): string | null => {
    28→  // Try to get from active instance first (foreground)
    29→  const instanceUserId = MatrixService.instance?.userId();
    30→  if (instanceUserId) return instanceUserId;
    31→
    32→  // Fall back to stored credentials (works in background)
    33→  const credentials = MatrixStorage.getLoginCredentials();
    34→  return credentials?.userId || null;
    35→};
    36→
    37→/**
    38→ * Ensure MatrixService is initialized for background decryption
    39→ * Uses lightweight initialization that doesn't start sync service
    40→ */
    41→const ensureServiceInitialized = async (): Promise<boolean> => {
    42→  const notificationClient = MatrixService.getNotificationClient();
    43→  if (notificationClient) return true;
    44→
    45→  // Foreground: create notification client if possible
    46→  if (MatrixService.instance) {
    47→    const client = await MatrixService.ensureNotificationClient();
    48→    return !!client;
    49→  }
    50→
    51→  // Try to restore session with lightweight background method
    52→  try {
    53→    const restored = await MatrixService.restoreSessionForBackground();
    54→    return restored;
    55→  } catch (error) {
    56→    console.error("[Push] Failed to restore session:", error);
    57→    return false;
    58→  }
    59→};
    60→
    61→const handleReceivedMessage = async (
    62→  message: FirebaseMessagingTypes.RemoteMessage,
    63→) => {
    64→  const data = message.data as unknown as NotificationData;
    65→  if (!data) return;
    66→
    67→  // Skip notifications for own messages (works in both foreground and background)
    68→  const currentUserId = getCurrentUserId();
    69→  if (currentUserId && data.sender === currentUserId) return;
    70→
    71→  const isCallOnIOS =
    72→    Platform.OS === "ios" &&
    73→    (data.type === "m.call.invite" || data.type === "m.call.member");
    74→
    75→  if (isCallOnIOS) {
    76→    // Skip if sync-based detection already triggered CallKit for this room
    77→    if (CallKitService.isRingingForRoom(data.room_id)) return;
    78→
    79→    CallKitService.displayIncomingCall({
    80→      roomId: data.room_id,
    81→      roomName: data.room_name || data.sender_display_name || data.sender,
    82→      senderDisplayName: data.sender_display_name || data.sender,
    83→    });
    84→    return;
    85→  }
    86→
    87→  const notificationId = message.messageId || `msg_${Date.now()}`;
    88→  const formattedMessage = formatLocalPushNotificationMessage(data);
    89→
    90→  if (!formattedMessage) return;
    91→
    92→  // Decrypt encrypted messages, then check if it's a call or a regular message
    93→  if (data.type === "m.room.encrypted" && data.room_id && data.event_id) {
    94→    try {
    95→      // Always ensure service is initialized for encrypted messages
    96→      const initialized = await ensureServiceInitialized();
    97→      if (!initialized) return;
    98→
    99→      // Check if the decrypted event is a call — route to CallKit on iOS
   100→      if (Platform.OS === "ios") {
   101→        const isCall = await isDecryptedEventCall(data.room_id, data.event_id);
   102→
   103→        if (isCall) {
   104→          // Skip if sync-based detection already triggered CallKit for this room
   105→          if (CallKitService.isRingingForRoom(data.room_id)) return;
   106→
   107→          const roomName = MatrixService.getRoomInfo(
   108→            data.room_id,
   109→          )?.displayName();
   110→
   111→          CallKitService.displayIncomingCall({
   112→            roomId: data.room_id,
   113→            roomName:
   114→              roomName ||
   115→              data.room_name ||
   116→              data.sender_display_name ||
   117→              data.sender,
   118→            senderDisplayName: data.sender_display_name || data.sender,
   119→          });
   120→          return;
   121→        }
   122→      }
   123→
   124→      const roomName = MatrixService.getRoomInfo(data.room_id)?.displayName();
   125→      const decryptedContent = await getDecryptedEventContent(
   126→        data.room_id,
   127→        data.event_id,
   128→      );
   129→
   130→      if (decryptedContent) {
   131→        await NotifeeService.create({
   132→          title:
   133→            roomName ||
   134→            data.room_name ||
   135→            data.sender_display_name ||
   136→            data.sender ||
   137→            "Unknown Sender",
   138→          message: `${data.sender_display_name || data.sender}: ${decryptedContent}`,
   139→          id: notificationId,
   140→          data: { room_id: data.room_id },
   141→        });
   142→      } else {
   143→        await NotifeeService.create({
   144→          title: formattedMessage.title,
   145→          message: formattedMessage.message,
   146→          id: notificationId,
   147→          data: { room_id: formattedMessage.room_id },
   148→        });
   149→      }
   150→    } catch (error) {
   151→      console.error("[Push] Failed to decrypt:", error);
   152→    }
   153→
   154→    return;
   155→  }
   156→
   157→  // For non-encrypted messages, show directly
   158→  await NotifeeService.create({
   159→    title: formattedMessage.title,
   160→    message: formattedMessage.message,
   161→    id: notificationId,
   162→    data: { room_id: formattedMessage.room_id },
   163→  });
   164→};
   165→
   166→const handleNotificationPress = async (
   167→  message: FirebaseMessagingTypes.RemoteMessage | null,
   168→  isInitialNotification: boolean,
   169→) => {
   170→  const data = message?.data as unknown as NotificationData;
   171→  const roomId = data?.room_id;
   172→
   173→  if (!roomId || typeof roomId !== "string") return;
   174→
   175→  // For initial notification (cold start), store the room_id
   176→  // and let the Splash screen handle navigation after session restoration
   177→  if (isInitialNotification) {
   178→    NotifeeService.setPendingRoomId(roomId);
   179→    return;
   180→  }
   181→
   182→  // Refresh the room list before navigating to ensure it's up to date
   183→  await MatrixService.refreshRoomList();
   184→
   185→  // For background events (app already running), navigate directly to room
   186→  NavigationContainerRef.navigate("room", { roomId });
   187→};
   188→
   189→export const PushNotificationsService = {
   190→  getToken: async () => await getToken(getMessaging()),
   191→  /** Register the device with Matrix homeserver for push notifications
   192→   * This should be called after successful login and after push permissions */
   193→  registerPusher: async () => {
   194→    try {
   195→      const fcmToken = await getToken(getMessaging());
   196→      await MatrixService.setPusher(fcmToken);
   197→      return true;
   198→    } catch (error) {
   199→      console.error("Failed to register push notifications:", error);
   200→      throw error;
   201→    }
   202→  },
   203→  /** Unregister the device from Matrix homeserver */
   204→  unregisterPusher: async () => {
   205→    try {
   206→      const fcmToken = await getMessaging().getToken();
   207→      await MatrixService.removePusher(fcmToken);
   208→      return true;
   209→    } catch (error) {
   210→      console.error("Failed to unregister push notifications:", error);
   211→      throw error;
   212→    }
   213→  },
   214→  registerListeners: async () => {
   215→    // Foreground message handler
   216→    onMessage(getMessaging(), async (message) => {
   217→      await handleReceivedMessage(message);
   218→    });
   219→
   220→    // When the application is opened from a quit state (cold start)
   221→    getInitialNotification(getMessaging()).then((remoteMessage) => {
   222→      handleNotificationPress(remoteMessage, true);
   223→    });
   224→
   225→    // When the application is running, but in the background
   226→    onNotificationOpenedApp(getMessaging(), (remoteMessage) => {
   227→      handleNotificationPress(remoteMessage, false);
   228→    });
   229→  },
   230→  /** Handle background messages - called from index.js */
   231→  handleBackgroundMessage: async (
   232→    remoteMessage: FirebaseMessagingTypes.RemoteMessage,
   233→  ) => {
   234→    await handleReceivedMessage(remoteMessage);
   235→  },
   236→  checkPermissions: async () => {
   237→    const result = await checkNotifications();
   238→    return result.status === RESULTS.GRANTED;
   239→  },
   240→  requestPermissions: async () => {
   241→    const result = await requestNotifications(["alert"]);
   242→    return result.status === RESULTS.GRANTED;
   243→  },
   244→  subscribeToTopic: async (topic: string) => {
   245→    await getMessaging().subscribeToTopic(topic);
   246→  },
   247→  unsubscribeFromTopic: async (topic: string) => {
   248→    await getMessaging().unsubscribeFromTopic(topic);
   249→  },
   250→};
