    68→export const ElementCall: React.FC<
    69→  NativeStackScreenProps<Routes, "elementCall">
    70→> = ({ route, navigation }) => {
    71→  const { roomId, roomName } = route.params;
    72→  const insets = useSafeAreaInsets();
    73→  const client = MatrixService.instance;
    74→  const room = client?.getRoom(roomId);
    75→  const webViewRef = useRef<WebView>(null);
    76→  const [callUrl, setCallUrl] = useState<string | null>(null);
    77→  const [loading, setLoading] = useState(true);
    78→  const [error, setError] = useState<string | null>(null);
    79→  const messageLoopRef = useRef<boolean>(false);
    80→  const messageLoopRunningRef = useRef<boolean>(false); // Track if loop is already running
    81→  const initializingRef = useRef<boolean>(false); // Track if initialization is in progress
    82→  const [isCallEnding, setIsCallEnding] = useState(false);
    83→  const [hasMediaPermissions, setHasMediaPermissions] = useState(false);
    84→
    85→  useEffect(() => {
    86→    initializeCall();
    87→
    88→    return () => {
    89→      // Stop message loop when component unmounts
    90→      messageLoopRef.current = false;
    91→      messageLoopRunningRef.current = false;
    92→      initializingRef.current = false;
    93→    };
    94→  }, [roomId]);
    95→
    96→  const initializeCall = async () => {
    97→    // Prevent multiple simultaneous initializations
    98→    if (initializingRef.current) {
    99→      console.log("Call initialization already in progress, skipping...");
   100→      return;
   101→    }
   102→
   103→    try {
   104→      if (!client || !room) throw new Error("Client or room not available");
   105→
   106→      initializingRef.current = true;
   107→      setLoading(true);
   108→      setError(null);
   109→
   110→      // Check native permissions for camera and microphone
   111→      const [cameraGranted, microphoneGranted] = await Promise.all([
   112→        checkPermission(PermissionType.CAMERA),
   113→        checkPermission(PermissionType.MICROPHONE),
   114→      ]);
   115→
   116→      // Store permission status to control WebView behavior
   117→      const permissionsGranted = cameraGranted && microphoneGranted;
   118→      setHasMediaPermissions(permissionsGranted);
   119→
   120→      if (!permissionsGranted) {
   121→        throw new Error(
   122→          "Camera and microphone permissions are required for video calls",
   123→        );
   124→      }
   125→
   126→      const { url } = await ElementCallService.startCall(roomId, room, client);
   127→
   128→      setCallUrl(url);
   129→
   130→      setTimeout(() => {
   131→        startMessageLoop();
   132→      }, 1000); // Give WebView time to initialize
   133→
   134→      setLoading(false);
   135→    } catch (err) {
   136→      console.error("Failed to initialize call:", err);
   137→      setError(
   138→        err instanceof Error ? err.message : "Failed to initialize call",
   139→      );
   140→      setLoading(false);
   141→      initializingRef.current = false; // Reset on error
   142→    }
   143→  };
   144→
   145→  const startMessageLoop = () => {
   146→    // Prevent multiple message loops from starting
   147→    if (messageLoopRunningRef.current) {
   148→      console.log("Message loop already running, skipping...");
   149→      return;
   150→    }
   151→
   152→    messageLoopRef.current = true;
   153→    messageLoopRunningRef.current = true;
   154→
   155→    // Run message loop in background (like Swift's Task.detached)
   156→    const runLoop = async () => {
   157→      while (messageLoopRef.current) {
   158→        try {
   159→          const message =
   160→            await ElementCallService.receiveMessagesFromWidget(roomId);
   161→
   162→          // recv() returns null when widget driver is done (like Swift)
   163→          if (!message) break;
   164→
   165→          if (webViewRef.current) {
   166→            const script = `
   167→              try {
   168→                // Use our custom inject method to avoid re-capturing
   169→                if (window.__rnInjectMessage) {
   170→                  window.__rnInjectMessage(${message});
   171→                } else {
   172→                  window.postMessage(${message}, '*');
   173→                }
   174→              } catch (e) {
   175→                console.error('Failed to post message:', e);
   176→              }
   177→            `;
   178→            webViewRef.current.injectJavaScript(script);
   179→          }
   180→
   181→          await new Promise((resolve) => setTimeout(resolve, 10));
   182→        } catch (err) {
   183→          console.error("Error in message loop:", err);
   184→          await new Promise((resolve) => setTimeout(resolve, 500));
   185→        }
   186→      }
