   232→        <Text
   233→          size={TextSize.medium}
   234→          color={Colors.white50}
   235→          margins={{ marginTop: 16 }}
   236→        >
   237→          Starting call...
   238→        </Text>
   239→      </View>
   240→    );
   241→  }
   242→
   243→  if (error || !callUrl) {
   244→    return (
   245→      <View style={styles.centerContainer}>
   246→        <Text size={TextSize.large} color={Colors.error}>
