   263→        </Text>
   264→      </View>
   265→    );
   266→  }
   267→
   268→  return (
   269→    <Block
   270→      flex={1}
   271→      background={Colors.black}
   272→      paddings={{ paddingTop: insets.top }}
   273→    >
   274→      <Block
   275→        flexDirection="row"
   276→        align="center"
   277→        justify="space-between"
   278→        paddings={{ paddingHorizontal: 16, paddingVertical: 12 }}
   279→        background={Colors.black}
