import { NavigationContainerRef } from "modules/navigation/const";
import { VerificationService } from "modules/verification/service/VerificationService";
import { type FC, useState } from "react";
import { Alert, Button } from "react-native";
import { Colors } from "shared/styles";

export const DebugHelpers: FC = () => {
  const [isHidden, setisHidden] = useState(false);

  const logout = () => {
    AuthService.logout();
    NavigationContainerRef.reset({
      index: 0,
      routes: [{ name: "login" }],
    });
  };

  const checkVerificationStatus = async () => {
    try {
      const details = await VerificationService.getVerificationDetails();
      const backupExists = await VerificationService.backupExists();

      const status = [
        `Verification State: ${details.verificationState}`,
        `Device Verified: ${details.isVerified ? "Yes ✓" : "No ✗"}`,
        `Device ID: ${details.deviceId || "Unknown"}`,
        `Backup Exists: ${backupExists ? "Yes" : "No"}`,
        details.userIdentity
          ? [
              `User Identity Verified: ${details.userIdentity.isVerified ? "Yes" : "No"}`,
              `Has Violation: ${details.userIdentity.hasVerificationViolation ? "Yes" : "No"}`,
              `Master Key: ${details.userIdentity.masterKey || "None"}`,
            ].join("\n")
          : "User Identity: Not available",
      ].join("\n\n");

      const buttons = [
        { text: "OK" },
        !details.isVerified
          ? {
              text: "How to Verify",
              onPress: () =>
                Alert.alert(
                  "Device Verification",
                  "To verify this device:\n\n" +
                    "1. Open Element X on another device\n" +
                    "2. Go to Settings → Security → Devices\n" +
                    '3. Find this device and tap "Verify"\n' +
                    "4. Compare the emoji sequences\n" +
                    "5. Confirm if they match\n\n" +
                    `Device ID: ${details.deviceId || "Unknown"}`,
                ),
            }
          : undefined,
      ].filter(
        (btn): btn is { text: string; onPress?: () => void } =>
          btn !== undefined,
      );

      Alert.alert(
        details.isVerified ? "Device Verified ✓" : "Device Not Verified",
        status,
        buttons,
      );
    } catch (error) {
      Alert.alert("Error", `Failed to check verification status: ${error}`);
    }
  };

  return null;

  if (isHidden) return null;

  return (
    <Block background={Colors.black} gap={8} align="center">
      <Text>Debug Helpers</Text>
      <Button title="Hide helpers" onPress={() => setisHidden(true)} />
      <Button
        title="Check Verification Status"
        onPress={checkVerificationStatus}
      />
      <Button title="Logout" onPress={logout} />
    </Block>
  );
};

