import {
  type FirebaseMessagingTypes,
  getInitialNotification,
  getMessaging,
  getToken,
  onMessage,
  onNotificationOpenedApp,
} from "@react-native-firebase/messaging";
import { AuthService } from "modules/auth/service/AuthService";
import { CallKitService } from "modules/call/service/CallKitService";
import { MatrixStorage } from "modules/matrix-client/const/matrix-storage";
import { MatrixCore } from "modules/matrix-client/services/MatrixCore";
import { NavigationContainerRef } from "modules/navigation/const";
import { MatrixNotificationService } from "modules/push-notifications/service/MatrixNotificationService";
import { RoomService } from "modules/room/service/RoomService";
import { Platform } from "react-native";
import {
  checkNotifications,
  requestNotifications,
  RESULTS,
} from "react-native-permissions";
import {
  formatLocalPushNotificationMessage,
  getDecryptedEventContent,
  isDecryptedEventCall,
} from "../util/formatLocalMessage";
import { NotifeeService } from "./NotifeeService";

/** Get the current user ID, works in both foreground and background */
const getCurrentUserId = (): string | null => {
  // Try to get from active instance first (foreground)
  const instanceUserId = MatrixCore.instance?.userId();
  if (instanceUserId) return instanceUserId;

  // Fall back to stored credentials (works in background)
  const credentials = MatrixStorage.getLoginCredentials();
  return credentials?.userId || null;
};

/**
 * Ensure MatrixService is initialized for background decryption
 * Uses lightweight initialization that doesn't start sync service
 */
const ensureServiceInitialized = async (): Promise<boolean> => {
  const notificationClient = MatrixNotificationService.getNotificationClient();
  if (notificationClient) return true;

  // Foreground: create notification client if possible
  if (MatrixCore.instance) {
    const client = await MatrixNotificationService.ensureNotificationClient();
    return !!client;
  }

  // Try to restore session with lightweight background method
  try {
    const restored = await AuthService.restoreSessionForBackground();
    return restored;
  } catch (error) {
    console.error("[Push] Failed to restore session:", error);
    return false;
  }
};

const handleReceivedMessage = async (
  message: FirebaseMessagingTypes.RemoteMessage,
) => {
  const data = message.data as unknown as NotificationData;
  if (!data) return;

  // Skip notifications for own messages (works in both foreground and background)
  const currentUserId = getCurrentUserId();
  if (currentUserId && data.sender === currentUserId) return;

  const isCallOnIOS =
    Platform.OS === "ios" &&
    (data.type === "m.call.invite" || data.type === "m.call.member");

  if (isCallOnIOS) {
    // Skip if sync-based detection already triggered CallKit for this room
    if (CallKitService.isRingingForRoom(data.room_id)) return;

    CallKitService.displayIncomingCall({
      roomId: data.room_id,
      roomName: data.room_name || data.sender_display_name || data.sender,
      senderDisplayName: data.sender_display_name || data.sender,
    });
    return;
  }

  const notificationId = message.messageId || `msg_${Date.now()}`;
  const formattedMessage = formatLocalPushNotificationMessage(data);

  if (!formattedMessage) return;

  // Decrypt encrypted messages, then check if it's a call or a regular message
  if (data.type === "m.room.encrypted" && data.room_id && data.event_id) {
    try {
      // Always ensure service is initialized for encrypted messages
      const initialized = await ensureServiceInitialized();
      if (!initialized) return;

      // Check if the decrypted event is a call — route to CallKit on iOS
      if (Platform.OS === "ios") {
        const isCall = await isDecryptedEventCall(data.room_id, data.event_id);

        if (isCall) {
          // Skip if sync-based detection already triggered CallKit for this room
          if (CallKitService.isRingingForRoom(data.room_id)) return;

          const roomName = RoomService.getRoomInfo(
            data.room_id,
          )?.displayName();

          CallKitService.displayIncomingCall({
            roomId: data.room_id,
            roomName:
              roomName ||
              data.room_name ||
              data.sender_display_name ||
              data.sender,
            senderDisplayName: data.sender_display_name || data.sender,
          });
          return;
        }
      }

      const roomName = RoomService.getRoomInfo(data.room_id)?.displayName();
      const decryptedContent = await getDecryptedEventContent(
        data.room_id,
        data.event_id,
      );

      if (decryptedContent) {
        await NotifeeService.create({
          title:
            roomName ||
            data.room_name ||
            data.sender_display_name ||
            data.sender ||
            "Unknown Sender",
          message: `${data.sender_display_name || data.sender}: ${decryptedContent}`,
          id: notificationId,
          data: { room_id: data.room_id },
        });
      } else {
        await NotifeeService.create({
          title: formattedMessage.title,
          message: formattedMessage.message,
          id: notificationId,
          data: { room_id: formattedMessage.room_id },
        });
      }
    } catch (error) {
      console.error("[Push] Failed to decrypt:", error);
    }

    return;
  }

  // For non-encrypted messages, show directly
  await NotifeeService.create({
    title: formattedMessage.title,
    message: formattedMessage.message,
    id: notificationId,
    data: { room_id: formattedMessage.room_id },
  });
};

const handleNotificationPress = async (
  message: FirebaseMessagingTypes.RemoteMessage | null,
  isInitialNotification: boolean,
) => {
  const data = message?.data as unknown as NotificationData;
  const roomId = data?.room_id;

  if (!roomId || typeof roomId !== "string") return;

  // For initial notification (cold start), store the room_id
  // and let the Splash screen handle navigation after session restoration
  if (isInitialNotification) {
    NotifeeService.setPendingRoomId(roomId);
    return;
  }

  // Refresh the room list before navigating to ensure it's up to date
  await MatrixCore.refreshRoomList();

  // For background events (app already running), navigate directly to room
  NavigationContainerRef.navigate("room", { roomId });
};

export const PushNotificationsService = {
  getToken: async () => await getToken(getMessaging()),
  /** Register the device with Matrix homeserver for push notifications
   * This should be called after successful login and after push permissions */
  registerPusher: async () => {
    try {
      const fcmToken = await getToken(getMessaging());
      await MatrixNotificationService.setPusher(fcmToken);
      return true;
    } catch (error) {
      console.error("Failed to register push notifications:", error);
      throw error;
    }
  },
  /** Unregister the device from Matrix homeserver */
  unregisterPusher: async () => {
    try {
      const fcmToken = await getMessaging().getToken();
      await MatrixNotificationService.removePusher(fcmToken);
      return true;
    } catch (error) {
      console.error("Failed to unregister push notifications:", error);
      throw error;
    }
  },
  registerListeners: async () => {
    // Foreground message handler
    onMessage(getMessaging(), async (message) => {
      await handleReceivedMessage(message);
    });

    // When the application is opened from a quit state (cold start)
    getInitialNotification(getMessaging()).then((remoteMessage) => {
      handleNotificationPress(remoteMessage, true);
    });

    // When the application is running, but in the background
    onNotificationOpenedApp(getMessaging(), (remoteMessage) => {
      handleNotificationPress(remoteMessage, false);
    });
  },
  /** Handle background messages - called from index.js */
  handleBackgroundMessage: async (
    remoteMessage: FirebaseMessagingTypes.RemoteMessage,
  ) => {
    await handleReceivedMessage(remoteMessage);
  },
  checkPermissions: async () => {
    const result = await checkNotifications();
    return result.status === RESULTS.GRANTED;
  },
  requestPermissions: async () => {
    const result = await requestNotifications(["alert"]);
    return result.status === RESULTS.GRANTED;
  },
  subscribeToTopic: async (topic: string) => {
    await getMessaging().subscribeToTopic(topic);
  },
  unsubscribeFromTopic: async (topic: string) => {
    await getMessaging().unsubscribeFromTopic(topic);
  },
};

import { MATRIX_ENDPOINTS } from "modules/matrix-client/const/matrix-enpoints";
import { MatrixCore } from "modules/matrix-client/services/MatrixCore";

export type PushRuleAction =
  | "notify"
  | "dont_notify"
  | "coalesce"
  | { set_tweak: string; value: string | boolean };

export type PushRuleCondition = {
  kind: string;
  key?: string;
  pattern?: string;
  is?: string;
};

export type PushRule = {
  rule_id: string;
  default: boolean;
  enabled: boolean;
  conditions?: PushRuleCondition[];
  actions: (PushRuleAction | string)[];
  pattern?: string;
};

export type PushRuleset = {
  global: {
    override?: PushRule[];
    content?: PushRule[];
    room?: PushRule[];
    sender?: PushRule[];
    underride?: PushRule[];
  };
};

export type NotificationLevel = "all" | "mentions" | "none";

/**
 * Service for managing Matrix Push Rules
 * Push rules determine when notifications should be sent to the user
 */
export const PushRulesService = {
  /** Get all push rules for the current user */
  getPushRules: async (): Promise<PushRuleset | null> => {
    if (!MatrixCore.instance) throw new Error("Client not initialized");

    const session = MatrixCore.instance.session();
    if (!session) throw new Error("No active session");

    try {
      const response = await fetch(
        `${session.homeserverUrl}${MATRIX_ENDPOINTS.PUSH_RULES_GET}`,
        {
          method: "GET",
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${session.accessToken}`,
          },
        },
      );

      if (!response.ok) {
        console.error("Failed to get push rules:", response.status);
        return null;
      }

      return await response.json();
    } catch (error) {
      console.error("Failed to fetch push rules:", error);
      return null;
    }
  },

  /** Enable or disable a specific push rule */
  setRuleEnabled: async (
    scope: string,
    kind: string,
    ruleId: string,
    enabled: boolean,
  ): Promise<boolean> => {
    if (!MatrixCore.instance) throw new Error("Client not initialized");

    const session = MatrixCore.instance.session();
    if (!session) throw new Error("No active session");

    try {
      const response = await fetch(
        `${session.homeserverUrl}${MATRIX_ENDPOINTS.PUSH_RULES_ENABLE}${scope}/${kind}/${ruleId}/enabled`,
        {
          method: "PUT",
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${session.accessToken}`,
          },
          body: JSON.stringify({ enabled }),
        },
      );

      return response.ok;
    } catch (error) {
      console.error("Failed to set rule enabled state:", error);
      return false;
    }
  },

  /** Set actions for a specific push rule */
  setRuleActions: async (
    scope: string,
    kind: string,
    ruleId: string,
    actions: (PushRuleAction | string)[],
  ): Promise<boolean> => {
    if (!MatrixCore.instance) throw new Error("Client not initialized");

    const session = MatrixCore.instance.session();
    if (!session) throw new Error("No active session");

    try {
      const response = await fetch(
        `${session.homeserverUrl}${MATRIX_ENDPOINTS.PUSH_RULES_SET}${scope}/${kind}/${ruleId}/actions`,
        {
          method: "PUT",
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${session.accessToken}`,
          },
          body: JSON.stringify({ actions }),
        },
      );

      return response.ok;
    } catch (error) {
      console.error("Failed to set rule actions:", error);
      return false;
    }
  },

  /**
   * Configure notifications for group chats (rooms with >2 members)
   * Uses the .m.rule.room_one_to_one underride rule
   */
  setGroupChatNotifications: async (
    level: NotificationLevel,
  ): Promise<boolean> => {
    // For group chats, we modify the underride rule that matches rooms with more than 2 members
    // The default rule is ".m.rule.message" which notifies for all messages
    // We need to disable it for "mentions" or "none"

    if (level === "none") {
      // Disable notifications for group chats
      return await PushRulesService.setRuleEnabled(
        "global",
        "underride",
        ".m.rule.message",
        false,
      );
    } else if (level === "mentions") {
      // For mentions only, disable the general message rule
      // but keep the mention rules enabled (they're in override/content)
      return await PushRulesService.setRuleEnabled(
        "global",
        "underride",
        ".m.rule.message",
        false,
      );
    } else {
      // For "all", enable the message rule
      return await PushRulesService.setRuleEnabled(
        "global",
        "underride",
        ".m.rule.message",
        true,
      );
    }
  },

  /**
   * Configure notifications for direct chats (1:1 rooms)
   * Uses the .m.rule.room_one_to_one underride rule
   */
  setDirectChatNotifications: async (
    level: NotificationLevel,
  ): Promise<boolean> => {
    const actions = getActionsForLevel(level);

    if (level === "none") {
      return await PushRulesService.setRuleEnabled(
        "global",
        "underride",
        ".m.rule.room_one_to_one",
        false,
      );
    } else if (level === "mentions") {
      // For direct chats, "mentions" doesn't make much sense, but we'll keep the rule enabled
      // with notify actions (all messages in DMs are somewhat like mentions)
      return await PushRulesService.setRuleActions(
        "global",
        "underride",
        ".m.rule.room_one_to_one",
        actions,
      );
    } else {
      // Enable and set actions for all messages
      const enabled = await PushRulesService.setRuleEnabled(
        "global",
        "underride",
        ".m.rule.room_one_to_one",
        true,
      );
      if (!enabled) return false;

      return await PushRulesService.setRuleActions(
        "global",
        "underride",
        ".m.rule.room_one_to_one",
        actions,
      );
    }
  },

  /**
   * Configure notifications for mentions (@username or @room)
   * Uses both newer override rules and older content rules for compatibility
   */
  setMentionsEnabled: async (enabled: boolean): Promise<boolean> => {
    // Newer Matrix spec uses override rules
    const overrideRules = [
      ".m.rule.is_user_mention", // New: Matches @username mentions
      ".m.rule.contains_display_name", // Matches display name
      ".m.rule.is_room_mention", // New: Matches @room mentions
      ".m.rule.roomnotif", // Old: Matches @room
    ];

    // Older Matrix spec uses content rules
    const contentRules = [
      ".m.rule.contains_user_name", // Old: Matches @username
    ];

    const overrideResults = await Promise.all(
      overrideRules.map((ruleId) =>
        PushRulesService.setRuleEnabled("global", "override", ruleId, enabled),
      ),
    );

    const contentResults = await Promise.all(
      contentRules.map((ruleId) =>
        PushRulesService.setRuleEnabled("global", "content", ruleId, enabled),
      ),
    );

    return [...overrideResults, ...contentResults].every((r) => r);
  },

  /**
   * Configure notifications for room invitations
   * Uses the .m.rule.invite_for_me override rule
   */
  setInvitationsEnabled: async (enabled: boolean): Promise<boolean> => {
    return await PushRulesService.setRuleEnabled(
      "global",
      "override",
      ".m.rule.invite_for_me",
      enabled,
    );
  },

  /** Get current notification settings from push rules */
  getNotificationSettings: async (): Promise<{
    groupChats: NotificationLevel;
    directChats: NotificationLevel;
    mentions: boolean;
    invitations: boolean;
  } | null> => {
    const rules = await PushRulesService.getPushRules();

    if (!rules || !rules.global) return null;

    // Determine group chat level
    const messageRule = rules.global.underride?.find(
      (r) => r.rule_id === ".m.rule.message",
    );
    const groupChats: NotificationLevel = messageRule?.enabled
      ? "all"
      : "mentions";

    // Determine direct chat level
    const dmRule = rules.global.underride?.find(
      (r) => r.rule_id === ".m.rule.room_one_to_one",
    );
    const directChats: NotificationLevel = dmRule?.enabled ? "all" : "none";

    // Determine mentions - check both new and old rules
    const newMentionRule = rules.global.override?.find(
      (r) => r.rule_id === ".m.rule.is_user_mention",
    );
    const oldMentionRule = rules.global.content?.find(
      (r) => r.rule_id === ".m.rule.contains_user_name",
    );
    const displayNameRule = rules.global.override?.find(
      (r) => r.rule_id === ".m.rule.contains_display_name",
    );

    // Mentions are enabled if any of the mention rules are enabled
    const mentions =
      (newMentionRule?.enabled ?? false) ||
      (oldMentionRule?.enabled ?? false) ||
      (displayNameRule?.enabled ?? true);

    // Determine invitations - check override section (not underride)
    const inviteRule = rules.global.override?.find(
      (r) => r.rule_id === ".m.rule.invite_for_me",
    );
    const invitations = inviteRule?.enabled ?? true;

    return {
      groupChats,
      directChats,
      mentions,
      invitations,
    };
  },
};

/** Helper function to get actions array for a notification level */
function getActionsForLevel(
  level: NotificationLevel,
): (PushRuleAction | string)[] {
  switch (level) {
    case "all":
      return [
        "notify",
        { set_tweak: "sound", value: "default" },
        { set_tweak: "highlight", value: false },
      ];
    case "mentions":
      return [
        "notify",
        { set_tweak: "sound", value: "default" },
        { set_tweak: "highlight", value: true },
      ];
    case "none":
      return ["dont_notify"];
  }
}

