  useEffect(() => {
    if (Platform.OS !== "ios" || roomList.length === 0) return;

    const currentActiveCallRoomIds = new Set<string>();

    for (const room of roomList) {
      if (!room.hasActiveRoomCall()) return;
      currentActiveCallRoomIds.add(room.id());
    }

    // Detect newly active calls (rooms that weren't active before)
    for (const roomId of currentActiveCallRoomIds) {
      if (prevActiveCallRoomIds.current.has(roomId)) continue;

      // Don't show CallKit if we initiated the call ourselves
      if (ElementCallService.getActiveCallRoomId() === roomId) continue;

      // Don't show if already ringing for this room (e.g. from push)
      if (CallKitService.isRingingForRoom(roomId)) continue;

      // Get room info for display
      const roomInfo = RoomService.getRoomInfo(roomId);
      const roomName = roomInfo?.displayName() ?? "Unknown Room";
      const currentUserId = MatrixCore.instance?.userId();

      // Don't ring for own calls
      if (!currentUserId) continue;

      CallKitService.displayIncomingCall({
        roomId,
        roomName,
        senderDisplayName: roomName,
      });
    }

    prevActiveCallRoomIds.current = currentActiveCallRoomIds;
  }, [roomList]);

  return <></>;
};

import type {
  RoomInterface,
  RoomMember,
} from "@unomed/react-native-matrix-sdk";
import { RoomService } from "modules/room/service/RoomService";
import { useCallback, useEffect, useState } from "react";
import { Alert } from "react-native";
import Toast from "react-native-toast-message";

enum LeaveRoomText {
  NOT_PUBLIC = `Are you sure that you want to leave this room? This room is not public and you won't be able to rejoin without an invite.`,
  EMPTY_ROOM = "Are you sure that you want to leave this room? You're the only person here. If you leave, no one will be able to join in the future, including you.",
  PUBLIC = "Are you sure that you want to leave the room?",
}

interface UseLeaveRoomOptions {
  onSuccess?: () => void;
}

export const useLeaveRoom = (
  room: RoomInterface,
  options?: UseLeaveRoomOptions,
) => {
  const [isLeavingRoom, setIsLeavingRoom] = useState(false);
  const [members, setMembers] = useState<RoomMember[]>([]);
  const [isRefreshingMembers, setIsRefreshingMembers] = useState(false);

  const refreshMembers = useCallback(async () => {
    setIsRefreshingMembers(true);
    try {
      const membersInfo = await room.members();
      const membersList = membersInfo.nextChunk(1000) ?? [];
      setMembers(membersList);
    } catch (error) {
      console.error("Failed to refresh members:", error);
    } finally {
      setIsRefreshingMembers(false);
    }
  }, [room]);

  useEffect(() => {
    refreshMembers();
  }, [refreshMembers]);

  const confirmLeaveRoom = useCallback(async () => {
    try {
      setIsLeavingRoom(true);
      await RoomService.leaveRoom(room.id());
      Toast.show({
        type: "success",
        text1: "Room left successfully",
      });
      options?.onSuccess?.();
    } catch (error) {
      console.error(error);
      Toast.show({
        type: "error",
        text1: "Failed to leave room",
      });
    } finally {
      setIsLeavingRoom(false);
    }
  }, [room, options]);

  const leaveRoom = useCallback(() => {
    const isEmptyRoom = Number(members.length) === 1;

    const textRoom = isEmptyRoom
      ? LeaveRoomText.EMPTY_ROOM
      : room.isPublic()
        ? LeaveRoomText.PUBLIC
        : LeaveRoomText.NOT_PUBLIC;

    Alert.alert("Leave Room", textRoom, [
      { text: "Cancel", style: "cancel" },
      { text: "Leave", onPress: confirmLeaveRoom },
    ]);
  }, [members, room, confirmLeaveRoom]);

  return {
    leaveRoom,
    isLeavingRoom,
    members,
    refreshMembers,
    isRefreshingMembers,
  };
};

