     1→import { Block, Text } from "@prototyp/skeletor";
     2→import type { NativeStackScreenProps } from "@react-navigation/native-stack";
     3→import {
     4→  Membership,
     5→  type RoomInterface,
     6→} from "@unomed/react-native-matrix-sdk";
     7→import { useAtom, useAtomValue } from "jotai";
     8→import { MatrixAtoms } from "modules/matrix-client/jotai";
     9→import { MatrixService } from "modules/matrix-client/services";
    10→import { TimelineAtoms } from "modules/timeline/jotai";
    11→import { type FC, useCallback, useMemo, useState } from "react";
    12→import { FlatList, StyleSheet } from "react-native";
    13→import Toast from "react-native-toast-message";
    14→import { Button, GoBackHeader, Loading, ScreenLayout } from "shared/components";
    15→import { Colors, TextSize } from "shared/styles";
    16→import { ForwardRoomItem } from "./fragments";
    17→
    18→export const ForwardMessage: FC<
    19→  NativeStackScreenProps<Routes, "forwardMessage">
    20→> = ({ navigation, route }) => {
    21→  const { currentRoomId } = route.params;
    22→  const [forwardPayload, setForwardPayload] = useAtom(
    23→    TimelineAtoms.forwardPayload,
    24→  );
    25→  const rooms = useAtomValue(MatrixAtoms.roomList);
    26→  const [isForwarding, setIsForwarding] = useState(false);
    27→  const [selectedRoomId, setSelectedRoomId] = useState<string | null>(null);
    28→
    29→  const filteredRooms = useMemo(() => {
    30→    return rooms
    31→      .filter((room) => {
    32→        const membership = room.membership();
    33→        return (
    34→          membership !== Membership.Banned &&
    35→          membership !== Membership.Left &&
    36→          membership !== Membership.Knocked &&
    37→          membership !== Membership.Invited
    38→        );
    39→      })
    40→      .filter((room) => room.id() !== currentRoomId);
    41→  }, [rooms]);
    42→
    43→  const handleToggleRoom = useCallback((room: RoomInterface) => {
    44→    const roomId = room.id();
    45→    setSelectedRoomId(roomId);
    46→  }, []);
    47→
    48→  const handleSend = useCallback(async () => {
    49→    if (!forwardPayload || !selectedRoomId) return;
    50→
    51→    try {
    52→      setIsForwarding(true);
    53→
    54→      await MatrixService.forwardMessage(
    55→        selectedRoomId,
    56→        forwardPayload.event,
    57→        forwardPayload.messageType,
    58→      );
    59→
    60→      setForwardPayload(null);
    61→
    62→      Toast.show({
    63→        type: "success",
    64→        text1: "Message forwarded",
    65→      });
    66→
    67→      navigation.replace("room", { roomId: selectedRoomId });
    68→    } catch (error) {
    69→      console.error("Failed to forward message:", error);
    70→      Toast.show({
    71→        type: "error",
    72→        text1: "Failed to forward message",
    73→      });
    74→    } finally {
    75→      setIsForwarding(false);
    76→    }
    77→  }, [forwardPayload, selectedRoomId, setForwardPayload]);
    78→
    79→  const keyExtractor = useCallback((item: RoomInterface) => item.id(), []);
    80→
    81→  if (!forwardPayload) return null;
    82→
    83→  return (
    84→    <ScreenLayout type="modal">
    85→      {isForwarding && <Loading text="Forwarding..." />}
    86→      <GoBackHeader
    87→        title="Forward to"
    88→        margins={{ marginBottom: 40 }}
    89→        rightComp={
    90→          <Button.Wrapper
    91→            onPress={handleSend}
    92→            disabled={isForwarding || !selectedRoomId}
    93→          >
    94→            <Text>Send</Text>
    95→          </Button.Wrapper>
    96→        }
    97→      />
    98→      <Block flex={1} background={Colors.black} gap={40}>
    99→        <Block
   100→          paddings={{ paddingHorizontal: 20, paddingVertical: 12 }}
   101→          background={Colors.blackMinus1}
   102→          border={{ borderRadius: 12 }}
   103→          gap={8}
   104→        >
   105→          <Text
   106→            size={TextSize.small}
   107→            color={Colors.white50}
   108→            textTransform="capitalize"
   109→          >
   110→            {forwardPayload.messageType}:
   111→          </Text>
   112→          <Text color={Colors.white80} numberOfLines={2}>
   113→            {forwardPayload.content}
   114→          </Text>
   115→        </Block>
   116→
   117→        <FlatList
   118→          data={filteredRooms}
   119→          renderItem={({ item }) => (
   120→            <ForwardRoomItem
   121→              room={item}
   122→              isSelected={selectedRoomId === item.id()}
   123→              onToggle={handleToggleRoom}
   124→            />
   125→          )}
   126→          keyExtractor={keyExtractor}
   127→          contentContainerStyle={styles.listContent}
   128→          ListEmptyComponent={
   129→            <Block
   130→              flex={1}
   131→              align="center"
   132→              justify="center"
   133→              paddings={{ paddingVertical: 40 }}
   134→            >
   135→              <Text size={TextSize.base} color={Colors.white50}>
   136→                No rooms available
   137→              </Text>
   138→            </Block>
   139→          }
   140→        />
   141→      </Block>
   142→    </ScreenLayout>
   143→  );
   144→};
   145→
   146→const styles = StyleSheet.create({
   147→  listContent: {
   148→    paddingBottom: 20,
   149→  },
   150→});
   151→

