    40→  };
    41→
    42→  if (isOutOfSync) {
    43→    return (
    44→      <Block
    45→        margins={{ marginBottom: 20 }}
    46→        paddings={[0, 20]}
    47→        width="100%"
    48→        gap={8}
    49→      >
