    27→  const [pendingPromotions, setPendingPromotions] = useState<Set<string>>(
    28→    new Set(),
    29→  );
    30→  const [pendingDemotions, setPendingDemotions] = useState<Set<string>>(
    31→    new Set(),
    32→  );
