    56→  const isModerator = useCallback(
    57→    (userId: string) => getLevel(userId) >= 50 && getLevel(userId) < 100,
    58→    [getLevel],
    59→  );
    60→
    61→  const myPowerLevel = useMemo(
    62→    () => userLevels.get(myUserId ?? "") ?? 0,
    63→    [userLevels, myUserId],
    64→  );
    65→  const canEdit = isAdminsScreen ? myPowerLevel >= 100 : myPowerLevel >= 50;
    66→
    67→  // Top list: quick summary of who currently has / will have the target role
    68→  // Admins screen: admins + pending promotions
    69→  // Moderators screen: admins + active moderators (not pending demotion) + pending promotions
    70→  const topList = useMemo(() => {
    71→    const top: RoomMember[] = [];
    72→    for (const m of joinedMembers) {
    73→      if (isAdmin(m.userId)) {
    74→        top.push(m);
    75→      } else if (isAdminsScreen) {
    76→        if (pendingPromotions.has(m.userId)) top.push(m);
