   116→    if (moderatorsSection.length > 0)
   117→      result.push({
   118→        title: "Moderators",
   119→        data: moderatorsSection,
   120→        key: "moderators",
   121→      });
   122→    if (membersSection.length > 0)
   123→      result.push({ title: "Members", data: membersSection, key: "members" });
   124→    return result;
   125→  }, [adminsSection, moderatorsSection, membersSection]);
   126→
   127→  const hasChanges = pendingPromotions.size > 0 || pendingDemotions.size > 0;
   128→
   129→  // Determine check state for a member in the 3 bottom sections
   130→  const isCheckedInSection = useCallback(
   131→    (userId: string): boolean => {
   132→      if (isAdmin(userId)) return true; // always checked
   133→
   134→      if (isAdminsScreen) {
   135→        return pendingPromotions.has(userId);
   136→      } else {
   137→        // Moderators screen
   138→        if (isModerator(userId)) {
   139→          return !pendingDemotions.has(userId); // checked unless pending demotion
   140→        }
   141→        return pendingPromotions.has(userId);
   142→      }
   143→    },
   144→    [isAdmin, isModerator, isAdminsScreen, pendingPromotions, pendingDemotions],
   145→  );
   146→
   147→  const handleToggle = useCallback(
   148→    (userId: string) => {
   149→      if (!canEdit || isAdmin(userId)) return;
   150→
   151→      if (isAdminsScreen) {
   152→        setPendingPromotions((prev) => {
   153→          const next = new Set(prev);
   154→          if (next.has(userId)) next.delete(userId);
   155→          else next.add(userId);
   156→          return next;
   157→        });
   158→      } else {
   159→        if (isModerator(userId)) {
   160→          setPendingDemotions((prev) => {
   161→            const next = new Set(prev);
   162→            if (next.has(userId)) next.delete(userId);
   163→            else next.add(userId);
   164→            return next;
   165→          });
