   198→    } finally {
   199→      setIsSaving(false);
   200→    }
   201→  };
   202→
   203→  useEffect(() => {
   204→    const fetchData = async () => {
   205→      try {
   206→        const roomInfo = MatrixService.getRoomInfo(room.id());
