    35→      await MatrixService.reportMessage(roomId, reportPayload.event, reason);
    36→
    37→      if (blockUser) await MatrixService.blockUser(reportPayload.senderId);
    38→
    39→      setReportPayload(null);
    40→
    41→      Toast.show({
    42→        type: "success",
    43→        text1: blockUser
    44→          ? "Message reported and user blocked"
