     1→import { Block } from "@prototyp/skeletor";
     2→import {
     3→  type EventTimelineItem,
     4→  type ImageMessageContent,
     5→  MessageType_Tags,
     6→  MsgLikeKind_Tags,
     7→  TimelineItemContent_Tags,
     8→  type VideoMessageContent,
     9→} from "@unomed/react-native-matrix-sdk";
    10→import { MatrixBaseURL } from "modules/matrix-client/const";
    11→import { MatrixService } from "modules/matrix-client/services";
    12→import { fetchMedia } from "modules/matrix-client/utils";
    13→import { type FC, useEffect, useState } from "react";
    14→import { Dimensions, Image } from "react-native";
    15→import Video from "react-native-video";
    16→import { Button, Loading } from "shared/components";
    17→import { Colors } from "shared/styles";
    18→
    19→const NUM_COLUMNS = 4;
    20→const SPACING = 2;
    21→const HORIZONTAL_SPACING = 40; // Each padding is 20px
    22→const { width: SCREEN_WIDTH } = Dimensions.get("window");
    23→const ITEM_SIZE =
    24→  (SCREEN_WIDTH - SPACING * (NUM_COLUMNS + 1) - HORIZONTAL_SPACING) /
    25→  NUM_COLUMNS;
    26→
    27→interface MediaThumbnailProps {
    28→  item: EventTimelineItem;
    29→  onPress: (uri: string | null, type?: "image" | "video") => void;
    30→}
    31→
    32→function getMediaInfo(item: EventTimelineItem): {
    33→  type: "image" | "video";
    34→  content: ImageMessageContent | VideoMessageContent;
    35→} | null {
    36→  if (item.content.tag === TimelineItemContent_Tags.MsgLike) {
    37→    const content = item.content.inner.content;
    38→    if (content.kind.tag === MsgLikeKind_Tags.Message) {
    39→      const msgType = content.kind.inner.content.msgType;
    40→      if (msgType?.tag === MessageType_Tags.Image) {
    41→        return { type: "image", content: msgType.inner.content };
    42→      }
    43→      if (msgType?.tag === MessageType_Tags.Video) {
    44→        return { type: "video", content: msgType.inner.content };
    45→      }
    46→    }
    47→  }
    48→  return null;
    49→}
    50→
    51→export const MediaThumbnail: FC<MediaThumbnailProps> = ({ item, onPress }) => {
    52→  const [uri, setUri] = useState<string | null>(null);
    53→  const [info, setInfo] = useState<{
    54→    type: "image" | "video";
    55→    content: ImageMessageContent | VideoMessageContent;
    56→  } | null>(null);
    57→  const [loading, setLoading] = useState(true);
    58→
    59→  useEffect(() => {
    60→    const loadMedia = async () => {
    61→      try {
    62→        setLoading(true);
    63→        const info = getMediaInfo(item);
    64→        setInfo(info);
    65→
    66→        if (!info?.content.source.url()) return;
    67→
    68→        const url = await fetchMedia({
    69→          serverUrl:
    70→            MatrixService.instance?.session().homeserverUrl || MatrixBaseURL,
    71→          mediaSource: info.content.source,
    72→          mimeType:
    73→            info.type === "image"
    74→              ? info.content.info?.mimetype || "image/jpeg"
    75→              : info.content.info?.mimetype || "video/mp4",
    76→        });
    77→
    78→        setUri(url);
    79→      } catch (e) {
    80→        console.error("Failed to load media thumbnail:", e);
    81→      } finally {
    82→        setLoading(false);
    83→      }
    84→    };
    85→
    86→    loadMedia();
    87→  }, [item]);
    88→
    89→  return (
    90→    <Button.Wrapper onPress={() => onPress(uri, info?.type)}>
    91→      {uri ? (
    92→        <Block
    93→          width={ITEM_SIZE}
    94→          height={ITEM_SIZE}
    95→          background={Colors.white20}
    96→          border={{
    97→            borderRadius: 4,
    98→          }}
    99→          overflow="hidden"
   100→        >
   101→          {info?.type === "image" ? (
   102→            <Image
   103→              source={{ uri }}
   104→              width={ITEM_SIZE}
   105→              height={ITEM_SIZE}
   106→              resizeMode="cover"
   107→            />
   108→          ) : (
   109→            <Video
   110→              source={{ uri }}
   111→              style={{
   112→                width: ITEM_SIZE,
   113→                height: ITEM_SIZE,
   114→              }}
   115→              resizeMode="contain"
   116→              controls
   117→              paused
   118→            />
   119→          )}
   120→        </Block>
   121→      ) : (
   122→        <Block
   123→          width={ITEM_SIZE}
   124→          height={ITEM_SIZE}
   125→          background={Colors.white20}
   126→          border={{ borderRadius: 4 }}
   127→          overflow="hidden"
   128→          align="center"
   129→          justify="center"
   130→        >
   131→          {loading && <Loading isFullScreen={false} />}
   132→        </Block>
   133→      )}
   134→    </Button.Wrapper>
   135→  );
   136→};
   137→

