    96→          if (member.userId !== userId) return member;
    97→
    98→          const newMembershipTag =
    99→            action === "ban"
   100→              ? MembershipState_Tags.Ban
   101→              : MembershipState_Tags.Leave; // For unban and remove, we change the membership to leave
   102→
   103→          return {
   104→            ...member,
   105→            membership: {
   106→              ...member.membership,
   107→              tag: newMembershipTag,
   108→            },
   109→          };
   110→        });
   111→      });
   112→
   113→      setTimeout(() => {
   114→        refreshMembers();
   115→      }, 2000);
   116→    },
   117→    [refreshMembers],
