   141→
   142→      const powerLevels = await MatrixService.getRoomPowerLevels(roomId);
   143→      if (!powerLevels) return;
   144→
   145→      const inviteLevel = Number(powerLevels.values().invite);
   146→      const myLevel = Number(powerLevels.userPowerLevels().get(myUserId) ?? 0);
   147→      setCanInvite(myLevel >= inviteLevel);
