    18→export const MembershipInfoMessage: FC<Props> = ({ event }) => {
    19→  const [displayName, setDisplayName] = useState<string>("Uknown");
    20→  const sender = event.senderProfile;
    21→  const senderId = event.sender;
    22→
    23→  useEffect(() => {
    24→    const fetch = async () => {
    25→      if (
    26→        sender?.tag === ProfileDetails_Tags.Ready &&
    27→        sender.inner.displayName
    28→      ) {
    29→        setDisplayName(sender.inner.displayName || "Unknown");
    30→        return;
    31→      }
    32→
    33→      if (senderId && MatrixService.instance) {
    34→        const profile = await MatrixService.instance.getProfile(senderId);
    35→        setDisplayName(profile.displayName || "Unknown");
    36→      }
    37→    };
    38→
    39→    fetch();
    40→  }, []);
    41→
    42→  const content = () => {
    43→    if (event.content.tag === TimelineItemContent_Tags.RoomMembership) {
    44→      const otherUserDisplayName =
    45→        event.content.inner.userDisplayName || event.content.inner.userId;
    46→
    47→      if (event.content.inner.change === MembershipChange.InvitationRejected) {
    48→        return `${displayName} rejected the invite`;
    49→      }
    50→      if (event.content.inner.change === MembershipChange.InvitationRevoked) {
    51→        return `${displayName} revoked the invite`;
    52→      }
    53→      if (event.content.inner.change === MembershipChange.Joined) {
    54→        return `${displayName} joined the room`;
    55→      }
    56→      if (event.content.inner.change === MembershipChange.Left) {
    57→        return `${displayName} left the room`;
    58→      }
    59→      if (event.content.inner.change === MembershipChange.Banned) {
    60→        return `${displayName} was banned from the room`;
    61→      }
    62→      if (event.content.inner.change === MembershipChange.Unbanned) {
    63→        return `${displayName} was unbanned from the room`;
    64→      }
    65→      if (event.content.inner.change === MembershipChange.Invited) {
    66→        return `${displayName} invited ${otherUserDisplayName} to the room`;
    67→      }
    68→      if (event.content.inner.change === MembershipChange.Kicked) {
    69→        return `${displayName} kicked ${otherUserDisplayName} from the room`;
    70→      }
    71→      if (event.content.inner.change === MembershipChange.InvitationAccepted) {
    72→        return `${displayName} joined the room`;
    73→      }
    74→      if (event.content.inner.change === MembershipChange.KickedAndBanned) {
