    23→
    24→interface Props {
    25→  roomId: string;
    26→}
    27→
    28→export const MessageContentBottomSheet: React.FC<Props> = ({ roomId }) => {
    29→  const ref = useRef<BottomSheetModal>(null);
    30→  const fadeIn = useRef(
    31→    animateSequence(
    32→      { opacity: [0, 1] },
    33→      {
    34→        duration: 200,
    35→      },
    36→    ),
    37→  ).current;
    38→  const [payload, setPayload] = useAtom(TimelineAtoms.longPressPayload);
    39→  const [userPowerLevel, setUserPowerLevel] = useState<number | null>(null);
    40→  const [redactLevel, setRedactLevel] = useState(50);
    41→  const avatarUrl = useMemo(() => {
    42→    return payload?.event.senderProfile.tag === ProfileDetails_Tags.Ready
    43→      ? payload?.event.senderProfile.inner.avatarUrl
    44→      : null;
    45→  }, [payload]);
    46→  const displayName = useMemo(() => {
    47→    return payload?.event.senderProfile.tag === ProfileDetails_Tags.Ready
    48→      ? payload?.event.senderProfile.inner.displayName
    49→      : undefined;
    50→  }, [payload]);
    51→  const isOwn = useMemo(() => payload?.event.isOwn, [payload]);
    52→  const isTextMessage = useMemo(
    53→    () => payload?.messageType === "text",
    54→    [payload],
    55→  );
    56→  const canEdit = useMemo(() => isOwn && isTextMessage, [isOwn, isTextMessage]);
    57→  const [isPinLoading, setIsPinLoading] = useState(false);
    58→  const pinnedEventIds = useAtomValue(TimelineAtoms.pinnedEventIds);
    59→  const eventId = useMemo(() => {
    60→    if (!payload) return null;
    61→    return getEventId(payload.event);
    62→  }, [payload]);
    63→  const isPinned = useMemo(() => {
    64→    if (!eventId) return false;
    65→    return pinnedEventIds.includes(eventId);
    66→  }, [eventId, pinnedEventIds]);
    67→  /** If the user is at least a moderator, they can pin messages */
    68→  const isModeratorAtLeast = useMemo(() => {
    69→    if (!userPowerLevel) return false;
    70→    return userPowerLevel >= 50;
    71→  }, [userPowerLevel]);
    72→  const setReplyPayload = useSetAtom(TimelineAtoms.replyPayload);
    73→  const setEditPayload = useSetAtom(TimelineAtoms.editPayload);
    74→  const setForwardPayload = useSetAtom(TimelineAtoms.forwardPayload);
    75→  const setReportPayload = useSetAtom(TimelineAtoms.reportPayload);
    76→  const setPinnedEventIds = useSetAtom(TimelineAtoms.pinnedEventIds);
    77→
    78→  const handleBottomSheetClose = useCallback(() => {
    79→    fadeIn.reverse(() => {
    80→      setPayload(null);
    81→    });
    82→  }, [fadeIn, setPayload]);
    83→
    84→  const handleReply = useCallback(() => {
    85→    if (!payload) return;
    86→    const eventId = getEventId(payload.event);
    87→    if (!eventId) return;
    88→
    89→    let mediaSource: TimelineReplyPayload["mediaSource"];
    90→
    91→    if (payload.messageType === "image" || payload.messageType === "video") {
    92→      const event = payload.event;
    93→      if (event.content.tag === TimelineItemContent_Tags.MsgLike) {
    94→        const kind = event.content.inner.content.kind;
    95→        if (kind?.tag === MsgLikeKind_Tags.Message) {
    96→          const msgType = kind.inner.content.msgType;
    97→          if (msgType?.tag === MessageType_Tags.Image) {
    98→            const imageContent = msgType.inner.content;
    99→            mediaSource = {
   100→              source: imageContent.source,
   101→              mimetype: imageContent.info?.mimetype || "image/jpeg",
   102→            };
   103→          } else if (msgType?.tag === MessageType_Tags.Video) {
   104→            const videoContent = msgType.inner.content;
   105→            mediaSource = {
   106→              source: videoContent.source,
   107→              mimetype: videoContent.info?.mimetype || "video/mp4",
   108→            };
   109→          }
   110→        }
   111→      }
   112→    }
   113→
   114→    setEditPayload(null);
   115→    setReplyPayload({
   116→      eventId,
   117→      senderName: displayName ?? payload.event.sender,
   118→      content: payload.content,
   119→      mediaSource,
   120→    });
   121→
   122→    ref.current?.dismiss();
   123→  }, [payload, displayName, setEditPayload, setReplyPayload]);
   124→
   125→  const handleEdit = useCallback(() => {
   126→    if (!payload?.event.isOwn || payload?.messageType !== "text") return;
   127→
   128→    setReplyPayload(null);
   129→    setEditPayload({
   130→      event: payload.event,
   131→      senderName: displayName ?? payload.event.sender,
   132→      content: payload.content,
   133→    });
   134→    ref.current?.dismiss();
   135→  }, [displayName, payload, setEditPayload, setReplyPayload]);
   136→
   137→  const handleForward = useCallback(() => {
   138→    if (!payload) return;
   139→
   140→    setForwardPayload(payload);
   141→    ref.current?.dismiss();
   142→    NavigationContainerRef.navigate("forwardMessage", {
   143→      currentRoomId: roomId,
   144→    });
   145→  }, [payload, setForwardPayload]);
   146→
   147→  const handleReport = useCallback(() => {
   148→    if (!payload) return;
   149→
   150→    setReportPayload({
   151→      event: payload.event,
   152→      senderId: payload.event.sender,
   153→      content: payload.content,
   154→    });
   155→    ref.current?.dismiss();
   156→    NavigationContainerRef.navigate("reportMessage", {
   157→      roomId,
   158→    });
   159→  }, [payload, setReportPayload, roomId]);
   160→
   161→  const handleDelete = useCallback(async () => {
   162→    if (!payload) return;
   163→
   164→    try {
   165→      await MatrixService.deleteMessage(roomId, payload.event);
   166→      setEditPayload(null);
   167→      setReplyPayload(null);
   168→    } catch (error) {
   169→      console.error("Failed to delete message:", error);
   170→    } finally {
   171→      ref.current?.dismiss();
   172→    }
   173→  }, [payload, roomId, setEditPayload, setReplyPayload]);
   174→
   175→  const handleCopy = () => {
   176→    if (!payload?.content) return;
   177→    Clipboard.setString(payload.content);
   178→    Toast.show({
   179→      text1: "Message copied to clipboard",
   180→      type: "success",
   181→    });
   182→    ref.current?.dismiss();
   183→  };
   184→
   185→  const handlePin = useCallback(async () => {
   186→    if (!eventId || isPinLoading) return;
   187→
   188→    setIsPinLoading(true);
   189→
   190→    try {
   191→      if (isPinned) {
   192→        await MatrixService.unpinMessage(roomId, eventId);
   193→        setPinnedEventIds((prev) => prev.filter((id) => id !== eventId));
   194→        Toast.show({
   195→          text1: "Message unpinned",
   196→          type: "success",
   197→        });
   198→
   199→        return;
   200→      }
   201→
   202→      await MatrixService.pinMessage(roomId, eventId);
   203→      setPinnedEventIds((prev) => [...prev, eventId]);
   204→      Toast.show({
   205→        text1: "Message pinned",
   206→        type: "success",
   207→      });
   208→    } catch (error) {
   209→      console.error("Failed to pin/unpin message:", error);
   210→      Toast.show({
   211→        text1: isPinned ? "Failed to unpin message" : "Failed to pin message",
   212→        type: "error",
   213→      });
   214→    } finally {
   215→      setIsPinLoading(false);
   216→      ref.current?.dismiss();
   217→    }
   218→  }, [eventId, isPinLoading, isPinned, roomId, setPinnedEventIds]);
   219→
   220→  usePreventSwipeBack(!!payload);
   221→
   222→  useEffect(() => {
   223→    if (!payload) return;
   224→
   225→    fadeIn.start();
   226→    ref.current?.present();
   227→  }, [payload, fadeIn]);
   228→
   229→  const canRedact = useMemo(
   230→    () => isOwn || (userPowerLevel !== null && userPowerLevel >= redactLevel),
   231→    [isOwn, userPowerLevel, redactLevel],
   232→  );
   233→
   234→  useEffect(() => {
   235→    MatrixService.getUserPowerLevel(roomId)
   236→      .then(setUserPowerLevel)
   237→      .catch(console.error);
   238→    MatrixService.getRoomPowerLevels(roomId)
   239→      .then((pl) => {
   240→        if (!pl) return;
   241→        setRedactLevel(Number(pl.values().redact));
   242→      })
   243→      .catch(console.error);
   244→  }, [roomId]);
   245→
   246→  if (!payload) return null;
   247→
   248→  return (
   249→    <Block
   250→      absolute
   251→      width="100%"
   252→      height="100%"
   253→      offsets={{ left: 0, bottom: 0 }}
   254→      animations={fadeIn.animations}
   255→      zIndex={9999}
   256→      background={Colors.black70}
   257→    >
   258→      <BottomSheetModal
   259→        ref={ref}
   260→        handleStyle={styles.handle}
   261→        handleIndicatorStyle={styles.handleIndicator}
   262→        backgroundStyle={styles.background}
   263→        enablePanDownToClose
   264→        enableDynamicSizing
   265→        onDismiss={handleBottomSheetClose}
   266→      >
   267→        <BottomSheetView>
   268→          <Block
   269→            paddings={{
   270→              paddingHorizontal: 20,
   271→              paddingBottom: 20,
   272→            }}
   273→            gap={16}
   274→            align="center"
   275→          >
   276→            <Block
   277→              width="100%"
   278→              flexDirection="row"
   279→              gap={16}
   280→              align="center"
   281→              justify="space-between"
   282→              margins={{ marginBottom: 32 }}
   283→            >
   284→              <Block flexDirection="row" gap={16} align="center" flex={1}>
   285→                <UserImage
   286→                  avatarUrl={avatarUrl}
   287→                  displayName={displayName}
   288→                  height={40}
   289→                  width={40}
   290→                />
   291→                <Block flex={1}>
   292→                  <Text color={Colors.primary}>{displayName}</Text>
   293→                  <Text numberOfLines={2} flex={1}>
   294→                    {payload.content}
   295→                  </Text>
   296→                </Block>
   297→              </Block>
   298→              <Text color={Colors.white50}>
   299→                {format(Number(payload.event.timestamp), "HH:mm")}
   300→              </Text>
   301→            </Block>
   302→            <Block width="100%">
   303→              <MessageContentListItem
   304→                title="Reply"
   305→                icon={require("assets/icons/reply.png")}
   306→                onPress={handleReply}
   307→              />
   308→              <MessageContentListItem
   309→                title="Forward"
   310→                icon={require("assets/icons/forward.png")}
   311→                onPress={handleForward}
   312→              />
   313→              {isModeratorAtLeast && (
   314→                <MessageContentListItem
   315→                  title={isPinned ? "Unpin" : "Pin"}
   316→                  icon={
   317→                    isPinned
