    32→export const RoomInput: FC<Props> = ({ roomId }) => {
    33→  const [message, setMessage] = useState("");
    34→  const [isRecording, setIsRecording] = useState(false);
    35→  const [isRecorded, setIsRecorded] = useState(false);
    36→  const [canSend, setCanSend] = useState(true);
    37→
    38→  useEffect(() => {
    39→    Promise.all([
    40→      MatrixService.getUserPowerLevel(roomId),
    41→      MatrixService.getRoomPowerLevels(roomId),
    42→    ])
    43→      .then(([userLevel, pl]) => {
    44→        const sendLevel = pl ? Number(pl.values().eventsDefault) : 0;
    45→        setCanSend((userLevel ?? 0) >= sendLevel);
    46→      })
    47→      .catch(console.error);
    48→  }, [roomId]);
    49→  const [replyPayload, setReplyPayload] = useAtom(TimelineAtoms.replyPayload);
    50→  const [editPayload, setEditPayload] = useAtom(TimelineAtoms.editPayload);
    51→  const hasPayload = !!replyPayload || !!editPayload;
    52→
    53→  const handleSendMessage = async () => {
    54→    if (!message) return;
    55→
    56→    try {
    57→      if (editPayload) {
    58→        await MatrixService.editMessage(roomId, editPayload.event, message);
    59→        setEditPayload(null);
    60→        return;
    61→      }
    62→
    63→      if (replyPayload) {
    64→        await MatrixService.replyToMessage(
    65→          roomId,
    66→          message,
    67→          replyPayload.eventId,
    68→        );
    69→        setReplyPayload(null);
    70→        return;
    71→      }
    72→
    73→      await MatrixService.sendMessage(roomId, message);
    74→    } catch (error) {
    75→      console.error("Failed to send message:", error);
    76→    } finally {
    77→      setMessage("");
    78→    }
    79→  };
    80→
    81→  useEffect(() => {
    82→    if (!editPayload) {
    83→      setMessage("");
    84→      return;
    85→    }
    86→    setMessage(editPayload.content);
    87→  }, [editPayload]);
    88→
    89→  useEffect(() => {
    90→    if (message || replyPayload) {
    91→      sendButtonTransition.start();
    92→      imageTransition.reverse();
    93→    } else {
    94→      sendButtonTransition.reverse();
    95→      imageTransition.start();
    96→    }
    97→  }, [message, replyPayload]);
    98→
    99→  useEffect(() => {
   100→    setReplyPayload(null);
   101→    setEditPayload(null);
   102→  }, [setEditPayload, setReplyPayload]);
   103→
   104→  useEffect(() => {
   105→    if (isRecording || isRecorded) {
   106→      imageTransition.reverse();
   107→      inputTransition.reverse();
   108→    } else {
   109→      imageTransition.start();
   110→      inputTransition.start();
   111→    }
   112→  }, [isRecording, isRecorded]);
   113→
   114→  if (!canSend) {
   115→    return (
   116→      <Block paddings={20} flexDirection="row" align="center" gap={8}>
   117→        <Image
   118→          source={require("assets/icons/warning.png")}
   119→          width={24}
   120→          height={24}
   121→          tintColor={Colors.white80}
   122→        />
   123→        <Text color={Colors.white80}>
   124→          You don't have permission to send messages
   125→        </Text>
   126→      </Block>
   127→    );
   128→  }
   129→
   130→  return (
   131→    <Block>
   132→      <Block
   133→        paddings={[20, 0, 20, 16]}
   134→        flexDirection="row"
   135→        align="flex-end"
   136→        justify="space-between"
   137→        height={hasPayload ? 158 : 88}
   138→        gap={message || replyPayload ? 0 : 8}
   139→      >
   140→        <Block
   141→          animations={imageTransition.animations}
   142→          height={48}
   143→          align="center"
   144→          justify="center"
   145→        >
   146→          <SendItemsList roomId={roomId} />
   147→        </Block>
   148→        <VoiceRecordButton
   149→          roomId={roomId}
   150→          message={message}
   151→          isRecording={isRecording}
   152→          isRecorded={isRecorded}
   153→          setIsRecorded={setIsRecorded}
   154→          setIsRecording={setIsRecording}
   155→        />
   156→        <Block
   157→          flex={isRecording || isRecorded ? 0 : 1}
   158→          animations={inputTransition.animations}
   159→          border={{ borderRadius: hasPayload ? 12 : 40 }}
   160→          background={Colors.white5}
   161→        >
   162→          <InputMessagePayload />
   163→          <Input
   164→            placeholder="Message"
   165→            value={message}
   166→            background="transparent"
   167→            autoCapitalize="none"
   168→            onChangeText={(value) => setMessage(value)}
   169→          />
   170→        </Block>
   171→        <Block
   172→          animations={sendButtonTransition.animations}
   173→          height={48}
   174→          overflow="hidden"
   175→        >
   176→          <Button.Wrapper disabled={!message} onPress={handleSendMessage}>
   177→            <Block
   178→              height={48}
   179→              width={48}
   180→              align="center"
   181→              justify="center"
   182→              background={Colors.primary}
   183→              border={{
   184→                borderRadius: 24,
   185→              }}
   186→              margins={{ marginLeft: 8 }}
   187→            >
   188→              <Image
   189→                source={require("assets/icons/paper-plane-right.png")}
   190→                width={24}
   191→                height={24}
   192→              />
   193→            </Block>
   194→          </Button.Wrapper>
   195→        </Block>
   196→      </Block>
   197→    </Block>
   198→  );
   199→};
