     5→import { checkPermission, PermissionType } from "modules/permissions/utils";
     6→import { RecorderService } from "modules/recorder-player/services/recording-service-factory";
     7→import { getTimeDuration, removeFile } from "modules/recorder-player/utils";
     8→import { TimelineAtoms } from "modules/timeline/jotai";
     9→import type { FC } from "react";
    10→import { useEffect, useRef, useState } from "react";
    11→import { Alert, AppState, Image, Linking, StyleSheet } from "react-native";
    12→import RNBlobUtil from "react-native-blob-util";
    13→import { Toast } from "react-native-toast-message/lib/src/Toast";
    14→import { Button } from "shared/components";
    15→import { Colors } from "shared/styles";
    16→import { AudioIndicator } from "../audio-indicator";
    17→
    18→const playButtonTransition = animateParallel(
    19→  { opacity: [0, 1], width: [0, 48] },
    20→  { duration: 200, native: false },
    21→);
    22→
    23→interface Props {
    24→  roomId: string;
    25→  isRecording: boolean;
    26→  isRecorded: boolean;
    27→  message: string;
    28→  setIsRecorded: (isRecorded: boolean) => void;
    29→  setIsRecording: (isRecording: boolean) => void;
    30→}
    31→
    32→const normalizePath = (path: string) => path.replace("file://", "");
    33→
    34→export const VoiceRecordButton: FC<Props> = ({
    35→  roomId,
    36→  isRecording,
    37→  isRecorded,
    38→  message,
    39→  setIsRecorded,
    40→  setIsRecording,
    41→}) => {
    42→  const durationMs = useRef(0);
    43→  const [duration, setDuration] = useState(0);
    44→  const recordingPath = useRef<string | null>(null);
    45→  const [isSending, setIsSending] = useState(false);
    46→  const replyPayload = useAtomValue(TimelineAtoms.replyPayload);
    47→
    48→  const startRecording = async () => {
    49→    try {
    50→      const hasMic = await checkPermission(PermissionType.MICROPHONE);
    51→      if (!hasMic) {
    52→        Alert.alert(
    53→          "Microphone permission required",
    54→          "Please grant microphone permission to record voice messages.",
    55→          [
    56→            {
    57→              text: "Cancel",
    58→              style: "cancel",
    59→            },
    60→            {
    61→              text: "Open settings",
    62→              onPress: () => Linking.openSettings(),
    63→            },
    64→          ],
    65→        );
    66→        return;
    67→      }
    68→
    69→      RecorderService.createListener((e) => {
    70→        setDuration(e.currentPosition);
    71→        durationMs.current = e.currentPosition;
    72→      });
    73→
    74→      await RecorderService.start();
    75→      setIsRecording(true);
    76→      setIsRecorded(true);
    77→    } catch (error) {
    78→      Toast.show({ type: "error", text1: "Failed to start recording" });
    79→      console.error(error);
    80→    }
    81→  };
    82→
    83→  const stopRecording = async () => {
    84→    try {
    85→      const path = await RecorderService.stop();
    86→      RecorderService.removeListener();
    87→      recordingPath.current = normalizePath(path);
    88→      setIsRecording(false);
    89→    } catch (error) {
    90→      Toast.show({
    91→        type: "error",
    92→        text1:
    93→          error instanceof Error ? error.message : "Failed to stop recording",
    94→      });
    95→      console.error(error);
    96→    }
    97→  };
    98→
    99→  const sendRecording = async () => {
   100→    try {
   101→      setIsSending(true);
   102→      setIsRecorded(false);
   103→
   104→      if (isRecording) await stopRecording();
   105→
   106→      if (!recordingPath.current) return;
   107→
   108→      const stats = await RNBlobUtil.fs.stat(recordingPath.current);
   109→
   110→      const room = MatrixService.instance?.getRoom(roomId);
   111→      if (!room) return Promise.reject(new Error("Room not found"));
   112→      const timeline = await room.timeline();
   113→
   114→      timeline.sendAudio(
   115→        {
   116→          source: new UploadSource.File({
   117→            filename: recordingPath.current.replace("file://", ""),
   118→          }),
   119→          caption: undefined,
   120→          formattedCaption: undefined,
   121→          mentions: undefined,
   122→          inReplyTo: undefined,
   123→        },
   124→        {
   125→          duration: durationMs.current,
   126→          size: BigInt(stats.size || 0),
   127→          mimetype: "audio/m4a",
   128→        },
   129→      );
   130→
   131→      // Don't immediately delete the recording - the SDK needs it for upload
   132→      // Clean up UI state but keep the file so it can be played while uploading
   133→      setDuration(0);
   134→      durationMs.current = 0;
   135→      recordingPath.current = null;
   136→    } catch (error) {
   137→      Toast.show({ type: "error", text1: "Failed to send voice message" });
   138→      console.error(error);
   139→    } finally {
   140→      setIsSending(false);
   141→    }
   142→  };
   143→
   144→  const removeRecording = async () => {
   145→    if (!recordingPath.current) return;
   146→    await removeFile(recordingPath.current);
   147→    setDuration(0);
   148→    durationMs.current = 0;
   149→    recordingPath.current = null;
   150→  };
   151→
   152→  const deleteRecording = async () => {
   153→    try {
   154→      if (isRecording) await stopRecording();
   155→      await removeRecording();
   156→      setIsRecorded(false);
   157→    } catch {
   158→      Toast.show({ type: "error", text1: "Failed to delete recording" });
   159→    }
   160→  };
   161→
   162→  useEffect(() => {
   163→    /**Stop the recording when the app goes to background */
   164→    const listener = AppState.addEventListener("change", (nextAppState) => {
   165→      if (nextAppState.match(/inactive|background/) && isRecording) {
   166→        stopRecording();
   167→      }
   168→    });
   169→
   170→    return () => listener.remove();
   171→  }, [isRecording]);
   172→
   173→  useEffect(() => {
   174→    if (message || isRecording || isRecorded || replyPayload) {
   175→      playButtonTransition.reverse();
   176→    } else playButtonTransition.start();
   177→  }, [message, isRecording, isRecorded, replyPayload]);
   178→
   179→  return (
   180→    <Block flexDirection="row" flex={isRecording || isRecorded ? 1 : 0} gap={8}>
   181→      <Block
   182→        height={48}
   183→        align="center"
   184→        justify="center"
   185→        animations={playButtonTransition.animations}
   186→      >
   187→        <Button.Outline
   188→          disabled={isSending}
   189→          style={styles.container}
   190→          onPress={startRecording}
   191→        >
   192→          <Image
   193→            source={require("assets/icons/microphone.png")}
   194→            style={styles.image}
   195→          />
   196→        </Button.Outline>
   197→      </Block>
   198→      {(isRecording || isRecorded) && (
   199→        <Block flexDirection="row" flex={1} gap={8}>
   200→          <Button.Wrapper
   201→            disabled={isSending}
   202→            style={styles.container}
   203→            onPress={deleteRecording}
   204→          >
   205→            <Image
   206→              source={require("assets/icons/trash.png")}
   207→              tintColor={Colors.error}
   208→              style={styles.image}
   209→            />
   210→          </Button.Wrapper>
   211→          <Block
   212→            flex={1}
   213→            align="center"
   214→            gap={12}
   215→            flexDirection="row"
   216→            height={44}
   217→            paddings={[10, 16]}
   218→            background={Colors.white20}
   219→            border={{ borderRadius: 40 }}
   220→          >
   221→            <AudioIndicator runAnimation={isRecording} />
   222→            <Text>{getTimeDuration(duration)}</Text>
   223→          </Block>
   224→          <Button.Wrapper
   225→            style={styles.container}
   226→            disabled={isSending}
   227→            onPress={isRecording ? stopRecording : sendRecording}
   228→          >
   229→            <Block
   230→              height={48}
   231→              width={48}
   232→              align="center"
   233→              justify="center"
   234→              background={isRecording ? Colors.white20 : Colors.primary}
   235→              border={{
   236→                borderRadius: 24,
   237→              }}
   238→            >
   239→              <Image
   240→                source={
   241→                  isRecording
   242→                    ? require("assets/icons/stop.png")
   243→                    : require("assets/icons/paper-plane-right.png")
   244→                }
   245→                style={styles.image}
   246→              />
   247→            </Block>
   248→          </Button.Wrapper>
   249→        </Block>
   250→      )}
   251→    </Block>
   252→  );
   253→};
   254→
   255→const styles = StyleSheet.create({
   256→  container: {
   257→    width: 48,
   258→    height: 48,
   259→    alignItems: "center",
   260→    justifyContent: "center",
   261→  },
   262→  image: {
   263→    width: 24,
   264→    height: 24,
   265→  },
   266→});
