     1→import { Block, Text } from "@prototyp/skeletor";
     2→import type { NativeStackScreenProps } from "@react-navigation/native-stack";
     3→import { MatrixService } from "modules/matrix-client/services";
     4→import { useMemo, useState } from "react";
     5→import {
     6→  Dimensions,
     7→  FlatList,
     8→  Image,
     9→  KeyboardAvoidingView,
    10→  StyleSheet,
    11→} from "react-native";
    12→import { Toast } from "react-native-toast-message/lib/src/Toast";
    13→import Video from "react-native-video";
    14→import {
    15→  Button,
    16→  GoBackHeader,
    17→  Input,
    18→  Loading,
    19→  ScreenLayout,
    20→} from "shared/components";
    21→import { Colors, TextSize } from "shared/styles";
    22→
    23→const MAX_DIMENSION = 140;
    24→
    25→const DEVICE_HEIGHT = Dimensions.get("window").height;
    26→
    27→const isVideo = (asset: Asset) => asset.type?.startsWith("video/");
    28→
    29→const handleImageSize = (asset: Asset) => {
    30→  const originalWidth = asset.width ?? 0;
    31→  const originalHeight = asset.height ?? 0;
    32→  const scaleRatio = Math.min(
    33→    MAX_DIMENSION / originalWidth,
    34→    MAX_DIMENSION / originalHeight,
    35→    1,
    36→  );
    37→  const targetWidth = Math.round(originalWidth * scaleRatio);
    38→  const targetHeight = Math.round(originalHeight * scaleRatio);
    39→
    40→  return { width: targetWidth, height: targetHeight };
    41→};
    42→
    43→export const SendImages: React.FC<
    44→  NativeStackScreenProps<Routes, "sendImages">
    45→> = ({ route, navigation }) => {
    46→  const { roomId, images } = route.params;
    47→  const [currentMedia, setCurrentMedia] = useState(images);
    48→  const [currentMediaIndex, setCurrentMediaIndex] = useState(0);
    49→  const [isSending, setIsSending] = useState(false);
    50→  // Store captions for each media item by index
    51→  const [captions, setCaptions] = useState<Record<number, string>>({});
    52→  const activeMedia = useMemo(() => {
    53→    return currentMedia[currentMediaIndex];
    54→  }, [currentMedia, currentMediaIndex]);
    55→  const isVertical = useMemo(() => {
    56→    if (!activeMedia) return false;
    57→    return (
    58→      handleImageSize(activeMedia).width < handleImageSize(activeMedia).height
    59→    );
    60→  }, [activeMedia]);
    61→
    62→  const handleSendMedia = async () => {
    63→    try {
    64→      setIsSending(true);
    65→      const tasks = currentMedia.map(async (asset, index) => {
    66→        if (!asset?.uri) {
    67→          return Promise.reject(new Error("No uri found"));
    68→        }
    69→
    70→        const caption = captions[index];
    71→        await MatrixService.sendMedia(roomId, asset, caption);
    72→      });
    73→
    74→      const results = await Promise.allSettled(tasks);
    75→      const failures = results.filter((r) => r.status === "rejected");
    76→      if (failures.length) {
    77→        failures.forEach((failure) => {
    78→          console.error(failure.reason);
    79→        });
    80→        throw new Error("Failed to send some media");
    81→      }
    82→      navigation.goBack();
    83→    } catch (error) {
    84→      console.error(error);
    85→      Toast.show({
    86→        type: "error",
    87→        text1: error instanceof Error ? error.message : "Failed to send media",
    88→      });
    89→    } finally {
    90→      setIsSending(false);
    91→    }
    92→  };
    93→
    94→  const handleImagePress = (index: number) => {
    95→    if (index === currentMediaIndex) {
    96→      const newImages = currentMedia.filter((_, i) => i !== index);
    97→      setCurrentMedia(newImages);
    98→      setCurrentMediaIndex(Math.min(currentMediaIndex, newImages.length - 1));
    99→      // Remove caption for deleted media and reindex remaining captions
   100→      const newCaptions: Record<number, string> = {};
   101→      Object.keys(captions).forEach((key) => {
   102→        const oldIndex = Number.parseInt(key, 10);
   103→        if (oldIndex < index) {
   104→          newCaptions[oldIndex] = captions[oldIndex];
   105→        } else if (oldIndex > index) {
   106→          newCaptions[oldIndex - 1] = captions[oldIndex];
   107→        }
   108→      });
   109→      setCaptions(newCaptions);
   110→      return;
   111→    }
   112→
   113→    setCurrentMediaIndex(index);
   114→  };
   115→
   116→  const handleCaptionChange = (text: string) => {
   117→    setCaptions((prev) => ({
   118→      ...prev,
   119→      [currentMediaIndex]: text,
   120→    }));
   121→  };
   122→
   123→  return (
   124→    <ScreenLayout background={Colors.blackMinus1}>
   125→      {isSending && <Loading text="Sending media..." />}
   126→      <GoBackHeader isClose />
   127→      <KeyboardAvoidingView
   128→        style={{ flex: 1 }}
   129→        behavior="padding"
   130→        keyboardVerticalOffset={0}
   131→      >
   132→        <Block flex={1} align="center" justify="center">
   133→          <Block
   134→            height={DEVICE_HEIGHT - 400} //Estimated height of the keyboard
   135→            overflow="hidden"
   136→            margins={{ marginBottom: "auto" }}
   137→          >
   138→            {isVideo(activeMedia) ? (
   139→              <Video
   140→                source={{ uri: activeMedia.uri }}
   141→                style={{
   142→                  height: isVertical ? "100%" : "auto",
   143→                  width: isVertical ? "auto" : "100%",
   144→                  aspectRatio:
   145→                    handleImageSize(activeMedia).width /
   146→                    handleImageSize(activeMedia).height,
   147→                }}
   148→                resizeMode="contain"
   149→                controls
   150→                paused={false}
   151→              />
   152→            ) : (
   153→              <Image
   154→                source={{ uri: activeMedia.uri }}
   155→                width={handleImageSize(activeMedia).width}
   156→                height={handleImageSize(activeMedia).height}
   157→                style={{
   158→                  height: isVertical ? "100%" : "auto",
   159→                  width: isVertical ? "auto" : "100%",
   160→                  aspectRatio:
   161→                    handleImageSize(activeMedia).width /
   162→                    handleImageSize(activeMedia).height,
   163→                }}
   164→              />
   165→            )}
   166→          </Block>
   167→
   168→          <Block
   169→            flex={1}
   170→            justify="flex-end"
   171→            absolute
   172→            width="100%"
   173→            offsets={{ bottom: 0 }}
   174→            gap={20}
   175→          >
   176→            <Block width="100%" gap={4} align="flex-start">
