    17→export const VerifyPin: React.FC<
    18→  NativeStackScreenProps<Routes, "verifyPin">
    19→> = ({ navigation, route }) => {
    20→  const [pin, setPin] = useState<string[]>(["", "", "", ""]);
    21→  const inputRefs = useRef<(TextInput | null)[]>([]);
    22→  const screenLockPin = useAtomValue(StorageAtoms.screenLockPin);
    23→  const [screenLockAttempts, setScreenLockAttempts] = useAtom(
    24→    StorageAtoms.screenLockAttempts,
    25→  );
    26→  const hasWrongAttempts = Number(screenLockAttempts) > 0;
    27→  const isSettingsScreen = !!route.params?.isSettingsScreen;
    28→  const [isLoggingOut, setIsLoggingOut] = useState(false);
    29→
    30→  const handlePinChange = async (text: string, index: number) => {
    31→    if (text && !/^\d$/.test(text)) return;
    32→
    33→    const newPin = [...pin];
    34→    newPin[index] = text;
    35→    setPin(newPin);
    36→
    37→    // When 4th digit is entered, check if the PIN is correct
    38→    if (index === 3) {
    39→      const newPinString = newPin.join("");
    40→      if (newPinString === screenLockPin) {
    41→        setScreenLockAttempts("0");
    42→        navigation.replace(isSettingsScreen ? "screenLockSettings" : "home");
    43→        return;
    44→      }
    45→
    46→      // If the user misses the last attempt, logout the user
    47→      if (Number(screenLockAttempts) === 2) {
    48→        try {
    49→          setIsLoggingOut(true);
    50→          Toast.show({
    51→            type: "error",
    52→            text1: "You have missed the last attempt.",
    53→          });
    54→          await MatrixService.logout();
    55→          navigation.reset({
    56→            index: 1,
    57→            routes: [{ name: "welcome" }, { name: "login" }],
    58→          });
    59→        } catch (error) {
    60→          console.error("Failed to logout: ", error);
    61→          Toast.show({
    62→            type: "error",
    63→            text1: "Failed to logout",
    64→          });
    65→        } finally {
    66→          setIsLoggingOut(false);
    67→        }
    68→        return;
    69→      }
    70→
    71→      setScreenLockAttempts(String(Number(screenLockAttempts) + 1));
    72→      Toast.show({
    73→        type: "error",
    74→        text1: "PIN is incorrect. Please try again.",
    75→      });
    76→      setPin(["", "", "", ""]);
    77→      inputRefs.current[0]?.focus();
    78→      return;
    79→    }
    80→
    81→    // Move to next input if a digit was entered
    82→    inputRefs.current[index + 1]?.focus();
    83→  };
    84→
    85→  // Move to previous input on backspace
    86→  const handleKeyPress = (e: TextInputKeyPressEvent, index: number) => {
    87→    if (e.nativeEvent.key !== "Backspace" || pin[index] || index === 0) {
    88→      return;
    89→    }
    90→
    91→    const newPin = [...pin];
    92→    newPin[index - 1] = "";
    93→    setPin(newPin);
    94→    inputRefs.current[index - 1]?.focus();
    95→  };
    96→
    97→  return (
    98→    <ScreenLayout type="modal">
    99→      {isLoggingOut && <Loading text="Logging out..." />}
   100→      <Block flex={1} align="center" gap={40}>
   101→        {isSettingsScreen && <GoBackHeader margins={0} />}
   102→        <Image
   103→          height={100}
   104→          width={100}
   105→          source={require("assets/images/key.png")}
   106→        />
   107→        <Block gap={8}>
   108→          <Text size={TextSize.large} textAlign="center">
   109→            Enter your PIN
   110→          </Text>
   111→          <Text
   112→            color={hasWrongAttempts ? Colors.warning : Colors.white80}
   113→            textAlign="center"
   114→          >
   115→            {`You have ${3 - Number(screenLockAttempts)} attempts to enter the correct PIN.`}
   116→          </Text>
   117→          {hasWrongAttempts && (
   118→            <Text color={Colors.warning} textAlign="center">
   119→              If you forget this PIN, you will be logged out out of the app
   120→            </Text>
   121→          )}
   122→        </Block>
   123→
   124→        <Block flexDirection="row" gap={12} pointerEvents="none">
   125→          {pin.map((digit, index) => (
   126→            <TextInput
   127→              key={index}
   128→              ref={(ref) => {
   129→                inputRefs.current[index] = ref;
   130→              }}
   131→              style={styles.input}
   132→              value={digit}
   133→              onChangeText={(text) => handlePinChange(text, index)}
   134→              onKeyPress={(e) => handleKeyPress(e, index)}
   135→              keyboardType="number-pad"
   136→              maxLength={1}
   137→              selectTextOnFocus={false}
   138→              autoFocus={index === 0}
   139→            />
   140→          ))}
   141→        </Block>
   142→      </Block>
   143→    </ScreenLayout>
   144→  );
   145→};
